def f(mapp, x, y, number, dep, answer):
    if dep == 2:
        answer.add(number)
        return
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for dx, dy in dirs:
        nxtx, nxty = x + dx, y + dy
        if 0 <= nxtx < 2 and 0 <= nxty < 2:
            f(mapp, nxtx, nxty, number + mapp[nxtx][nxty], dep + 1, answer)

